-- BoothGen 2.67.0: template library (Standard layouts designed in Super Admin, client options, operator templates
-- offered to clients). Run in the Neon SQL Editor on the PRODUCTION branch, all at once. Nothing is dropped.
BEGIN;

-- Operators' own templates can be offered in their clients' design picker
ALTER TABLE "booth_design_templates" ADD COLUMN IF NOT EXISTS "offerToClients" BOOLEAN NOT NULL DEFAULT false;
-- Standard layouts an operator hid from their library and their clients' picker
ALTER TABLE "tenants" ADD COLUMN IF NOT EXISTS "hiddenStandardTemplates" JSONB NOT NULL DEFAULT '[]';

-- Standard layouts: BoothGen's own set. Re-running updates them in place.
-- Earlier test Standard templates are hidden (isActive = false), not deleted.
UPDATE "booth_design_templates" SET "isActive" = false, "isPublished" = false, "updatedAt" = NOW()
  WHERE "tenantId" IS NULL AND "id" NOT IN ('std_l_full_bleed', 'std_l_classic', 'std_l_logo_panel', 'std_l_side_by_side', 'std_l_three_row', 'std_l_trio_logo', 'std_l_grid4', 'std_p_full_bleed', 'std_p_classic', 'std_p_instant', 'std_p_trio_logo', 'std_p_grid4', 'std_s_three', 'std_s_three_top', 'std_s_four');

